class Solution {
  public List<Integer> findCoins(int[] numWays) {
    int n = numWays.length;
    long[] dp = new long[n + 1];
    dp[0] = 1;
    List<Integer> coins = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
      long diff = numWays[i - 1] - dp[i];
      if (diff == 0) continue;
      if (diff != 1) return new ArrayList<>();
      coins.add(i);
      for (int s = i; s <= n; s++) dp[s] += dp[s - i];
    }
    return coins;
  }
}
